SELECT p.pid,t.tid,s.ts,s.dur,s.state,s.io_wait,s.blocked_function FROM thread_state s JOIN thread t USING(utid) JOIN process p USING(upid) WHERE p.pid IN (6920,7811,8210,8781,9240,10147,11271,11673,12754,13301) AND t.tid IN (6942,6942,7831,7831,8234,8234,8803,8803,9264,9264,10169,10169,11295,11295,11696,11696,12777,12777,13325,13325) AND s.ts < 394520308700 AND s.ts+s.dur > 169261925000 ORDER BY p.pid,t.tid,s.ts;
